{
  "findings": [
    {
      "check_id": "CKV_AWS_88",
      "title": "EC2 instance should not have public IP.",
      "resource": "aws_instance.ubuntu[1]",
      "severity": "MEDIUM",
      "explanation": "The second EC2 instance (index 1) is configured to have a public IP address, which increases the risk of unauthorized access. Public IPs should be avoided unless absolutely necessary."
    },
    {
      "check_id": "CKV_AWS_126",
      "title": "Ensure that detailed monitoring is enabled for EC2 instances",
      "resource": "aws_instance.ubuntu[2]",
      "severity": "MEDIUM",
      "explanation": "Detailed monitoring is not enabled for the third EC2 instance (index 2). Enabling detailed monitoring provides better observability and helps in identifying performance issues."
    },
    {
      "check_id": "CKV_AWS_135",
      "title": "Ensure that EC2 is EBS optimized",
      "resource": "aws_instance.ubuntu[2]",
      "severity": "MEDIUM",
      "explanation": "The third EC2 instance (index 2) is not configured to be EBS optimized. EBS optimization improves the performance of EBS volumes attached to the instance."
    },
    {
      "check_id": "CKV_AWS_79",
      "title": "Ensure Instance Metadata Service Version 1 is not enabled",
      "resource": "aws_instance.ubuntu[2]",
      "severity": "MEDIUM",
      "explanation": "The third EC2 instance (index 2) does not explicitly disable Instance Metadata Service Version 1 (IMDSv1). IMDSv1 is less secure and susceptible to SSRF attacks compared to IMDSv2."
    },
    {
      "check_id": "CKV_AWS_8",
      "title": "Ensure all data stored in the Launch configuration or instance Elastic Blocks Store is securely encrypted",
      "resource": "aws_instance.ubuntu[2]",
      "severity": "MEDIUM",
      "explanation": "The third EC2 instance (index 2) does not ensure that its attached EBS volumes are encrypted. Unencrypted EBS volumes can expose sensitive data if compromised."
    },
    {
      "check_id": "CKV2_AWS_41",
      "title": "Ensure an IAM role is attached to EC2 instance",
      "resource": "aws_instance.ubuntu[2]",
      "severity": "MEDIUM",
      "explanation": "The third EC2 instance (index 2) does not have an IAM role attached. Without an IAM role, the instance cannot securely access AWS services or resources."
    }
  ],
  "patched_code": "resource "aws_instance" "ubuntu" {
  count = 3
  ami = data.aws_ami.ubuntu_14_04.image_id
  instance_type = "t2.micro"
  associate_public_ip_address = false
  subnet_id = aws_subnet.my_subnet.id

  ebs_optimized = (count.index == 2 ? true : false)
  monitoring = (count.index == 2 ? true : false)

  metadata_options {
    http_tokens = "required"
    http_endpoint = "enabled"
  }

  root_block_device {
    encrypted = true
  }

  iam_instance_profile = (count.index == 2 ? aws_iam_instance_profile.my_instance_profile.name : null)
}

resource "aws_iam_instance_profile" "my_instance_profile" {
  name = "my-instance-profile"
  role = aws_iam_role.my_instance_role.name
}

resource "aws_iam_role" "my_instance_role" {
  name = "my-instance-role"
  assume_role_policy = <<EOF
{
  "Version": "2012-10-17",
  "Statement": [
    {
      "Effect": "Allow",
      "Principal": {
        "Service": "ec2.amazonaws.com"
      },
      "Action": "sts:AssumeRole"
    }
  ]
}
EOF
}

resource "aws_iam_role_policy" "my_instance_policy" {
  name = "my-instance-policy"
  role = aws_iam_role.my_instance_role.name
  policy = <<EOF
{
  "Version": "2012-10-17",
  "Statement": [
    {
      "Effect": "Allow",
      "Action": "s3:ListBucket",
      "Resource": "*"
    }
  ]
}
EOF
}",
  "fix_summary": "The patch removes the public IP from the second instance, enables detailed monitoring and EBS optimization for the third instance, enforces IMDSv2, encrypts the root EBS volume, and attaches an IAM role to the third instance for secure access to AWS services."
}
